$numeros = [7, 12, 3, 18, 5, -1]; // -1 es condición de parada
$idx = 0;
do {
    $valor = $numeros[$idx];
    if ($valor === -1) break;
    echo "Procesando: $valor\n";
    $idx++;
} while ($idx &lt; count($numeros));
// Procesando: 7
// Procesando: 12
// Procesando: 3
// Procesando: 18
