array_unshift($numeros, 0);        // añade al inicio

echo count($numeros); // 8 (6 originales menos 2 extraídos, más 2 añadidos)
?&gt;
&lt;?php
// Comprobar si un valor existe
$frutas = ["manzana", "pera", "naranja"];

var_dump(in_array("pera", $frutas));      // true
var_dump(in_array("uva", $frutas));       // false

// Posición de un elemento
$pos = array_search("naranja", $frutas);
echo $pos; // 2
?&gt;

Arrays asociativos
Las claves son cadenas de texto en lugar de números:
&lt;?php
$alumno = [
    "nombre" =&gt; "Laura",
    "curso"  =&gt; "2º DAW",
    "nota"   =&gt; 8.5,
];

echo $alumno["nombre"]; // Laura
echo $alumno["nota"];   // 8.5

// Añadir o modificar
$alumno["email"] = "laura@example.com";
$alumno["nota"]  = 9.0;

// Comprobar si una clave existe
var_dump(array_key_exists("email", $alumno)); // true
var_dump(isset($alumno["telefono"]));          // false
?&gt;
&lt;?php
// Recorrer con foreach
$capitales = [
    "España"   =&gt; "Madrid",
    "Francia"  =&gt; "París",
    "Portugal" =&gt; "Lisboa",
];

foreach ($capitales as $pais =&gt; $capital) {
    echo "$pais → $capital\n";
}
// España → Madrid
// Francia → París
// Portugal → Lisboa
?&gt;
&lt;?php
// Eliminar una clave
$config = ["debug" =&gt; true, "cache" =&gt; false, "timeout" =&gt; 30];
unset($config["debug"]);
print_r($config);
// Array ( [cache] =&gt; [timeout] =&gt; 30 )
?&gt;






AdvertenciaErrores frecuentes



Acceder a una clave que no existe lanza un aviso en PHP 8. Siempre usa ?? para dar un valor por defecto seguro para los casos en los que no exista la key del array:
&lt;?php
$datos = ["nombre" =&gt; "Ana"];

echo $datos["telefono"];         // Warning: Undefined array key
echo $datos["telefono"] ?? "—";  // —   (sin aviso)
?&gt;

Arrays multidimensionales
Arrays que contienen otros arrays — el patrón habitual para representar listas de registros:
&lt;?php
$alumnos = [
    ["nombre" =&gt; "Laura", "nota" =&gt; 8.5, "aprobado" =&gt; true],
    ["nombre" =&gt; "Marc",  "nota" =&gt; 4.0, "aprobado" =&gt; false],
    ["nombre" =&gt; "Aisha", "nota" =&gt; 9.2, "aprobado" =&gt; true],
];

echo $alumnos[0]["nombre"] . "&lt;br&gt;"; // Laura
echo $alumnos[1]["nota"] . "&lt;br&gt;";   // 4

foreach ($alumnos as $a) {
    $estado = $a["aprobado"] ? "Aprobado" : "Suspendido";
    echo "{$a['nombre']}: {$a['nota']} ({$estado})&lt;br&gt;";
}

// Laura: 8.5 (Aprobado)
// Marc: 4 (Suspendido)
// Aisha: 9.2 (Aprobado)
?&gt;
&lt;?php
// Añadir, modificar y filtrar sobre multidimensional
$productos = [
    ["nombre" =&gt; "Camiseta", "precio" =&gt; 15.0, "stock" =&gt; 10],
    ["nombre" =&gt; "Pantalón", "precio" =&gt; 35.0, "stock" =&gt; 0],
    ["nombre" =&gt; "Zapatos",  "precio" =&gt; 60.0, "stock" =&gt; 5],
];

// Contar los disponibles
$disponibles = 0;
foreach ($productos as $p) {
    if ($p["stock"] &gt; 0) $disponibles++;
}
echo "Disponibles: $disponibles / " . count($productos);
// Disponibles: 2 / 3
?&gt;

Funciones de orden superior
Es una función que recibe otra función como argumento (o devuelve una función) — en vez de decirle a PHP cómo recorrer el array paso a paso con un bucle, le dices qué hacer con cada elemento, y ella se encarga del recorrido por ti.
array_map, array_filter y array_reduce son las tres funciones de orden superior más usadas con arrays, y cada una resuelve un problema distinto.






NotaNota



Las tres evitan bucles explícitos (for, foreach) y, sobre todo, evitan el error típico de olvidar declarar o reiniciar una variable acumuladora fuera del bucle.



array_map

Transforma cada elemento y devuelve un array nuevo del mismo tamaño (por ejemplo, aplicar IVA a todos los precios).

&lt;?php
$precios = [10.0, 25.0, 8.0, 40.0];

// Aplicar IVA a todos
$conIva = array_map(fn($p) =&gt; round($p * 1.21, 2), $precios);
print_r($conIva);
// Array ( [0] =&gt; 12.1 [1] =&gt; 30.25 [2] =&gt; 9.68 [3] =&gt; 48.4 )
?&gt;
&lt;?php
// Aplicar a arrays asociativos dentro de un array
$alumnos = [
    ["nombre" =&gt; "Laura", "nota" =&gt; 7.0],
    ["nombre" =&gt; "Marc",  "nota" =&gt; 4.5],
    ["nombre" =&gt; "Aisha", "nota" =&gt; 9.1],
];

// Añadir campo 'aprobado' a cada alumno
$conEstado = array_map(function($a) {
    $a["aprobado"] = $a["nota"] &gt;= 5;
    return $a;
}, $alumnos);

foreach ($conEstado as $a) {
    $s = $a["aprobado"] ? "Aprobado" : "Suspendido";
    echo "{$a['nombre']}: $s&lt;br&gt;";
}
// Laura: Aprobado
// Marc: Suspendido
// Aisha: Aprobado
?&gt;


array_filter

Selecciona/Filtra los elementos que cumplen una condición, devolviendo un array más pequeño (o igual) que el original (por ejemplo, quedarte solo con los productos en stock).

&lt;?php
$numeros = [1, 2, 3, 4, 5, 6, 7, 8];

$pares = array_filter($numeros, fn($n) =&gt; $n % 2 === 0);
print_r(array_values($pares)); // reindexar con array_values
// Array ( [0] =&gt; 2 [1] =&gt; 4 [2] =&gt; 6 [3] =&gt; 8 )
?&gt;
&lt;?php
$productos = [
    ["nombre" =&gt; "Teclado", "precio" =&gt; 25.0, "stock" =&gt; 0],
    ["nombre" =&gt; "Ratón",   "precio" =&gt; 15.0, "stock" =&gt; 8],
    ["nombre" =&gt; "Monitor", "precio" =&gt; 180.0,"stock" =&gt; 3],
];

// Solo los que tienen stock
$disponibles = array_filter($productos, fn($p) =&gt; $p["stock"] &gt; 0);

foreach ($disponibles as $p) {
    echo "{$p['nombre']}: {$p['precio']} €\n";
}
// Ratón: 15 €
// Monitor: 180 €
?&gt;






AdvertenciaErrores frecuentes



array_filter conserva las claves originales. Si después necesitas índices 0, 1, 2..., aplica array_values():
&lt;?php
$pares = array_filter([1,2,3,4,5], fn($n) =&gt; $n % 2 === 0);
var_dump(array_keys($pares));         // [1, 3]  — claves no consecutivas
var_dump(array_keys(array_values($pares))); // [0, 1]  — reindexado
?&gt;




array_reduce

Combina todos los elementos en un único valor de salida (por ejemplo, sumar el total de una compra).

&lt;?php
$notas = [7.5, 8.0, 6.5, 9.0, 5.5];

$suma = array_reduce($notas, fn($acum, $n) =&gt; $acum + $n, 0);
echo "Suma: $suma\n";      // Suma: 36.5
echo "Media: " . ($suma / count($notas)); // Media: 7.3
?&gt;
&lt;?php
// Agrupar productos por categoría con array_reduce
$items = [
    ["nombre" =&gt; "Manzana", "tipo" =&gt; "fruta"],
    ["nombre" =&gt; "Pan",     "tipo" =&gt; "panadería"],
    ["nombre" =&gt; "Pera",    "tipo" =&gt; "fruta"],
    ["nombre" =&gt; "Croissant","tipo"=&gt; "panadería"],
];

$agrupados = array_reduce($items, function($acum, $item) {
    $acum[$item["tipo"]][] = $item["nombre"];
    return $acum;
}, []);

print_r($agrupados);
// Array (
//   [fruta] =&gt; Array ( [0] =&gt; Manzana [1] =&gt; Pera )
//   [panadería] =&gt; Array ( [0] =&gt; Pan [1] =&gt; Croissant )
// )
?&gt;

Otras funciones útiles
&lt;?php
$catalogo = ["DAW2" =&gt; "Desarrollo Web", "DAM2" =&gt; "Apps Móviles", "ASIR2" =&gt; "Redes"];

// Ordenar por clave
ksort($catalogo);
print_r($catalogo);
// Array ( [ASIR2] =&gt; Redes [DAM2] =&gt; Apps Móviles [DAW2] =&gt; Desarrollo Web )

// Ordenar por valor (mantiene asociación clave-valor)
asort($catalogo);
print_r($catalogo);
// Array ( [DAM2] =&gt; Apps Móviles [DAW2] =&gt; Desarrollo Web [ASIR2] =&gt; Redes )

// Extraer solo claves o solo valores
print_r(array_keys($catalogo));   // Array ( [0] =&gt; DAM2 [1] =&gt; DAW2 [2] =&gt; ASIR2 )
print_r(array_values($catalogo)); // Array ( [0] =&gt; Apps Móviles [1] =&gt; Desarrollo Web [2] =&gt; Redes )
?&gt;
&lt;?php
// array_slice: extraer una porción
$letras = ["a","b","c","d","e","f"];
print_r(array_slice($letras, 2, 3));
// Array ( [0] =&gt; c [1] =&gt; d [2] =&gt; e )

// array_splice: extraer y (opcionalmente) insertar
$numeros = [1,2,3,4,5];
$extraidos = array_splice($numeros, 1, 2, [10, 20]);
print_r($numeros);    // Array ( [0] =&gt; 1 [1] =&gt; 10 [2] =&gt; 20 [3] =&gt; 4 [4] =&gt; 5 )
print_r($extraidos);  // Array ( [0] =&gt; 2 [1] =&gt; 3 )
?&gt;

